WITH exploded AS (SELECT id, customer_id, created_at, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW EXPLODE(items) x AS elem) SELECT *, COUNT(qty) OVER (PARTITION BY promo ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) qty_count_15m, AVG(qty) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) qty_avg_1h, ROUND(qty / SUM(qty) OVER (PARTITION BY customer_id, promo), 4) qty_share, CUME_DIST() OVER (ORDER BY qty DESC NULLS LAST) qty_cume_dist FROM exploded
